window.AVL_SOURCES = [{"label": "提交版（OJ 用）", "file": "catalan.py", "lang": "py", "stripped": "import sys\n\nMAXN = 18\n\ndef catalan_table(limit):\n    cat = [1]\n    for k in range(1, limit + 1):\n        cat.append(cat[k - 1] * (4 * k - 2) // (k + 1))\n    return cat\n\ndef make_reader():\n    buf = []\n\n    def nxt():\n        while not buf:\n            line = sys.stdin.readline()\n            if not line:\n                return None\n\n            buf.extend(reversed(line.split()))\n        return buf.pop()\n\n    return nxt\n\ndef is_uint(s):\n    if not s:\n        return False\n    for ch in s:\n        if ch < \"0\" or ch > \"9\":\n            return False\n    return True\n\ndef main():\n    nxt = make_reader()\n    cat = catalan_table(MAXN)\n\n    while True:\n        tok = nxt()\n        if tok is None:\n            break\n        if not is_uint(tok):\n            print(\"[!] n must be a decimal integer, got \" + repr(tok[:32]),\n                  file=sys.stderr)\n            return\n        if len(tok) > 9:\n\n            print(\"[!] n is far out of range [1, \" + str(MAXN) + \"]: a \"\n                  + str(len(tok)) + \"-digit number\", file=sys.stderr)\n            return\n        n = int(tok)\n        if n < 1 or n > MAXN:\n            print(\"[!] n out of range [1, \" + str(MAXN) + \"]: \" + str(n),\n                  file=sys.stderr)\n            return\n\n        print(cat[n])\n        sys.stdout.flush()\n\nif __name__ == \"__main__\":\n    main()\n", "original": "# -*- coding: utf-8 -*-\n#\n# 车厢调度 —— 栈能得到多少种输出序列（即卡特兰数）\n# ================================================\n# Input:  若干行，每行一个整数 n（1 <= n <= 18），**读到文件结束（EOF）**\n# Output: 对每个 n 输出一行，即可能的输出序列总数\n#\n# 判题格式（铁律 2）\n# -----------------\n# 题面写「输入有若干行，每行只含一个整数 n」，样例是 2 / 3  ->  2 / 5：\n# **没有 T 组数**，是\"多组读到 EOF\"。\n# 本仓库三种结束方式都出现过 —— 均分纸牌 = EOF、数字三角形 = H=0 哨兵、\n# LCS = 第 1 行 T 组数。**逐题从题面和样例确认，别拿上一题的习惯套下一题。**\n#\n# 算法：卡特兰数\n# --------------\n# 整个过程就是 n 次 push 和 n 次 pop 排成一列，唯一约束是**任何时刻 pop 的次数\n# 不能超过 push 的次数**（栈里没东西就弹不出来）。这样的合法操作序列数就是\n# 第 n 个卡特兰数：\n#\n#       Cat(n) = C(2n, n) / (n+1)\n#\n# 本题用它的整数递推（不需要大整数库，也不需要组合数函数）：\n#\n#       Cat(0) = 1\n#       Cat(k) = Cat(k-1) * (4k - 2) // (k + 1)\n#\n# 分子一定是 (k+1) 的倍数，所以 // 不会丢精度。\n#\n# 规模：n <= 18 时最大是 Cat(18) = 477638700，32 位整数都装得下\n#       （题面提示\"输出数据会很大\"，实际并没有超出 int；不过 C 版仍用 long long，\n#        换个题就不会栽跟头）。\n\nimport sys\n\nMAXN = 18\n\n\ndef catalan_table(limit):\n    \"\"\"返回列表 cat[0..limit]，cat[k] = 第 k 个卡特兰数。\n\n    递推：cat[0] = 1；cat[k] = cat[k-1] * (4k - 2) // (k + 1)。\n    预计算一次，多组输入直接查表。\n    \"\"\"\n    cat = [1]\n    for k in range(1, limit + 1):\n        cat.append(cat[k - 1] * (4 * k - 2) // (k + 1))\n    return cat\n\n\ndef make_reader():\n    \"\"\"每次吐一个空白分隔的 token，取完返回 None。\n\n    逐行 readline()，三种环境通用：OJ 上 EOF 时返回空串，\n    缓冲区自然空掉、循环结束，结果与 read() 一致。\n    \"\"\"\n    buf = []\n\n    def nxt():\n        while not buf:\n            line = sys.stdin.readline()\n            if not line:                  # EOF / Ctrl+Z\n                return None\n            # 反序入栈，下面 pop() 才是 O(1)。\n            # 若写成 buf.extend(line.split()) + buf.pop(0)，取队首是 O(n)，\n            # 一行里塞很多 token 时会退化成 O(n^2)（知识库记的 pop(0) 性能悬崖）。\n            buf.extend(reversed(line.split()))\n        return buf.pop()\n\n    return nxt\n\n\ndef is_uint(s):\n    \"\"\"s 是否为纯十进制数字串（允许前导零，拒绝空串 / 正负号 / 小数点）。\n\n    先校验再计算，是为了守住\"宁可中止也不错答\"：'1a' 这类 token 直接丢给\n    int() 侥幸能过，但 'abc' 会抛异常、'-1' 会被当成合法整数，都不好收拾。\n    \"\"\"\n    if not s:\n        return False\n    for ch in s:\n        if ch < \"0\" or ch > \"9\":\n            return False\n    return True\n\n\ndef main():\n    nxt = make_reader()\n    cat = catalan_table(MAXN)             # 一次算好 0..18，多组输入直接查表\n\n    while True:\n        tok = nxt()\n        if tok is None:                   # 读到 EOF：正常结束\n            break\n        if not is_uint(tok):\n            print(\"[!] n must be a decimal integer, got \" + repr(tok[:32]),\n                  file=sys.stderr)\n            return\n        if len(tok) > 9:\n            # ★ 必须先拦长度、再 int()：Python 3.11+ 对超过 4300 位的数字串\n            # 转 int 会**直接抛 ValueError**（给出 traceback），\n            # 而不是我们要的 [!] 报错（铁律 3）。\n            # 题面 n <= 18 只有 2 位，9 位已是极宽松的上限，与 C 版口径一致。\n            print(\"[!] n is far out of range [1, \" + str(MAXN) + \"]: a \"\n                  + str(len(tok)) + \"-digit number\", file=sys.stderr)\n            return\n        n = int(tok)\n        if n < 1 or n > MAXN:\n            print(\"[!] n out of range [1, \" + str(MAXN) + \"]: \" + str(n),\n                  file=sys.stderr)\n            return\n\n        print(cat[n])\n        sys.stdout.flush()                # 逐组刷出：敲一组立刻看到一组答案\n\n    # ★ 这里刻意\"逐组输出\"，而不是\"全部读完再一起输出\"。\n    # 本题是**读到 EOF 才结束**的格式：在终端 / PyCharm 里手敲时，\n    # 若把答案攒到读完再打，用户不按 Ctrl+Z（Windows）/ Ctrl+D（Linux）\n    # 就一个答案都看不到 —— 那正是\"输入了却没有任何输出\"的由来。\n    # 逐组输出能让他敲完第一组就看见结果，至少知道程序在正常干活。\n    #\n    # 对照：11的余数 是\"第 1 行 T 组数\"，读完 T 组自动结束，\n    #       那种格式才适合攒起来统一输出（见 11的余数/mod11.py）。\n    # ⚠️ 另外提醒：即使逐组输出，程序仍要等到 EOF 才会退出 ——\n    #    终端里敲完数据请按 Ctrl+Z 再回车（Windows）/ Ctrl+D（Linux）。\n    #    不想管这个就用管道：python catalan.py < input.txt\n\n\nif __name__ == \"__main__\":\n    main()\n"}, {"label": "详细版（本地学习）", "file": "catalan_detailed.py", "lang": "py", "stripped": "import math\nimport sys\n\nMAXN = 18\nBRUTE_LIMIT = 9\nLIST_LIMIT = 5\nTABLE_LIMIT = 10\n\ndef catalan_recur(limit):\n    cat = [1]\n    for k in range(1, limit + 1):\n        cat.append(cat[k - 1] * (4 * k - 2) // (k + 1))\n    return cat\n\ndef catalan_dp(n):\n    table = [[0] * (n + 1) for _ in range(n + 1)]\n    table[0][0] = 1\n    for i in range(n + 1):\n        for j in range(n + 1):\n            if i == 0 and j == 0:\n                continue\n            v = 0\n            if i >= 1:\n                v += table[i - 1][j]\n            if j >= 1 and j <= i:\n                v += table[i][j - 1]\n            table[i][j] = v\n    return table[n][n], table\n\ndef catalan_comb(n):\n    return math.factorial(2 * n) // (math.factorial(n) * math.factorial(n + 1))\n\ndef enumerate_outputs(n):\n    seen = []\n\n    def dfs(next_num, stack, out):\n        if len(out) == n:\n            seen.append(tuple(out))\n            return\n        if next_num <= n:\n            stack.append(next_num)\n            dfs(next_num + 1, stack, out)\n            stack.pop()\n        if stack:\n            v = stack.pop()\n            out.append(v)\n            dfs(next_num, stack, out)\n            out.pop()\n            stack.append(v)\n\n    dfs(1, [], [])\n    return seen\n\ndef show_dp_table(table, n):\n    w = max(5, len(str(table[n][n])) + 2)\n    print(\"    \" + \"\".rjust(5) + \"\".join((\"j=\" + str(j)).rjust(w)\n                                        for j in range(n + 1)))\n    for i in range(n + 1):\n        cells = []\n        for j in range(n + 1):\n            if j > i:\n                cells.append(\"--\".rjust(w))\n            else:\n                cells.append(str(table[i][j]).rjust(w))\n        print(\"    \" + (\"i=\" + str(i)).rjust(5) + \"\".join(cells))\n\ndef show_sequences(seqs, n):\n    for s in seqs:\n        print(\"      \" + \" \".join(str(x) for x in s))\n\ndef make_reader():\n    buf = []\n\n    def nxt():\n        while not buf:\n            line = sys.stdin.readline()\n            if not line:\n                return None\n\n            buf.extend(reversed(line.split()))\n        return buf.pop()\n\n    return nxt\n\ndef is_uint(s):\n    if not s:\n        return False\n    for ch in s:\n        if ch < \"0\" or ch > \"9\":\n            return False\n    return True\n\ndef main():\n    nxt = make_reader()\n    cat = catalan_recur(MAXN)\n\n    case = 0\n    answers = []\n\n    while True:\n        tok = nxt()\n        if tok is None:\n            break\n        if not is_uint(tok):\n            print(\"[!] n must be a decimal integer, got \" + repr(tok[:32]),\n                  file=sys.stderr)\n            return\n        if len(tok) > 9:\n\n            print(\"[!] n is far out of range [1, \" + str(MAXN) + \"]: a \"\n                  + str(len(tok)) + \"-digit number\", file=sys.stderr)\n            return\n        n = int(tok)\n        if n < 1 or n > MAXN:\n            print(\"[!] n out of range [1, \" + str(MAXN) + \"]: \" + str(n),\n                  file=sys.stderr)\n            return\n\n        case += 1\n        print(\"\")\n        print(\"=\" * 62)\n        print(\"Case \" + str(case) + \"    n = \" + str(n))\n        print(\"=\" * 62)\n\n        print(\"\")\n        print(\"[1] 暴力枚举：把所有合法的 push/pop 序列走一遍，收集不同的输出序列\")\n        brute = None\n        if n <= BRUTE_LIMIT:\n\n            seqs = sorted(enumerate_outputs(n))\n            brute = len(seqs)\n            print(\"    共 \" + str(len(seqs)) + \" 种\")\n            if n <= LIST_LIMIT:\n                print(\"    全部列出来（字典序）：\")\n                show_sequences(seqs, n)\n            else:\n                print(\"    （n > \" + str(LIST_LIMIT) + \"，序列太多，这里只报数量）\")\n        else:\n            print(\"    （n > \" + str(BRUTE_LIMIT) + \"，枚举太慢，跳过；\"\n                  \"看下面三套公式的结果）\")\n\n        print(\"\")\n        print(\"[2] 动态规划  table[i][j] = 已 push i 个、已 pop j 个 的方案数\")\n        print(\"    转移：table[i][j] = table[i-1][j] (push) + table[i][j-1] (pop，需 j<=i)\")\n        dp_ans, table = catalan_dp(n)\n        if n <= TABLE_LIMIT:\n            show_dp_table(table, n)\n        else:\n            print(\"    （n > \" + str(TABLE_LIMIT) + \"，表太大不打印）\")\n        print(\"    答案 table[\" + str(n) + \"][\" + str(n) + \"] = \" + str(dp_ans))\n\n        print(\"\")\n        print(\"[3] 卡特兰递推  Cat(k) = Cat(k-1) * (4k-2) // (k+1)\")\n        show_k = min(n, 12)\n        head = \" \".join(str(cat[k]) for k in range(show_k + 1))\n        if n <= show_k:\n            print(\"    Cat(0..\" + str(n) + \") = \" + head)\n        else:\n            print(\"    Cat(0..\" + str(show_k) + \") = \" + head\n                  + \"   (共 \" + str(n) + \" 步，中间省略)\")\n        recur_ans = cat[n]\n        print(\"    Cat(\" + str(n) + \") = \" + str(recur_ans))\n\n        print(\"\")\n        print(\"[4] 组合数公式  Cat(n) = C(2n, n) / (n+1)\")\n        c2n = math.factorial(2 * n) // (math.factorial(n) * math.factorial(n))\n        comb_ans = catalan_comb(n)\n        print(\"    C(\" + str(2 * n) + \", \" + str(n) + \") = \" + str(c2n)\n              + \"，\" + str(c2n) + \" / (\" + str(n) + \"+1) = \" + str(comb_ans))\n\n        print(\"\")\n        print(\"[5] Sum check 交叉验证\")\n        parts = []\n        if brute is not None:\n            parts.append(\"暴力 \" + str(brute))\n        parts.append(\"DP \" + str(dp_ans))\n        parts.append(\"递推 \" + str(recur_ans))\n        parts.append(\"组合 \" + str(comb_ans))\n        ok = (dp_ans == recur_ans == comb_ans) and (brute is None or brute == dp_ans)\n        print(\"    \" + \" == \".join(parts) + \"  ->  \" + (\"OK\" if ok else \"MISMATCH\"))\n        if not ok:\n            print(\"[!] Sum check FAILED for n = \" + str(n), file=sys.stderr)\n\n        print(\"\")\n        print(\"  >>> 答案: \" + str(recur_ans))\n\n        answers.append(recur_ans)\n        sys.stdout.flush()\n\n    if answers:\n        print(\"\")\n        print(\"=\" * 62)\n        print(\"OJ 标准格式输出（提交请用 catalan.py，本文件仅供本地学习）\")\n        print(\"=\" * 62)\n        for a in answers:\n            print(a)\n        sys.stdout.flush()\n\nif __name__ == \"__main__\":\n    main()\n", "original": "# -*- coding: utf-8 -*-\n\"\"\"\n车厢调度 —— 详细版\n==================\n⚠️ 仅本地学习用 —— 请勿提交本文件到 OJ！它输出完整推导过程，判题必 WA。\n   真正要提交的是同目录下的 catalan.py。\n\n对每组 n 依次做：\n\n  [1] 暴力枚举（n 较小时）—— 把所有合法的 push/pop 序列走一遍，\n      收集真正得到的不同输出序列，直接数出来\n  [2] 动态规划 —— table[i][j] = 已 push i 个、已 pop j 个的方案数，答案 table[n][n]\n  [3] 卡特兰递推 —— Cat(k) = Cat(k-1) * (4k-2) // (k+1)\n  [4] 组合数公式 —— Cat(n) = C(2n, n) / (n+1)\n  Sum check：四法必须给出同一个数，否则 stderr 报 MISMATCH\n\n为什么答案就是卡特兰数\n----------------------\n整个调度过程可以看成 n 次 push 与 n 次 pop 排成的一列操作，唯一的约束是：\n\n    任何时刻 pop 的次数都不能超过 push 的次数   （栈空则弹不出东西）\n\n这正是卡特兰数的标准组合意义之一（等同于\"n 对括号的正确匹配方式数\"），\n所以答案是 Cat(n) = C(2n, n) / (n+1)。\n\nInput:\n  若干行，每行一个整数 n（1 <= n <= 18），读到 EOF 结束\nOutput:\n  每组一段推导过程；文件末尾再按 OJ 标准格式输出一遍纯答案，便于逐字比对\n\"\"\"\n\nimport math\nimport sys\n\nMAXN = 18\nBRUTE_LIMIT = 9          # 暴力枚举的上限（Cat(9) = 4862，再大就慢了）\nLIST_LIMIT = 5           # 只有 n <= 5（最多 42 种）才把序列一条条列出来\nTABLE_LIMIT = 10         # 只有 n <= 10 才打印 DP 表\n\n\n# ---------------------------------------------------------------- 四套算法\n\ndef catalan_recur(limit):\n    \"\"\"卡特兰递推表 cat[0..limit]：cat[0]=1，cat[k] = cat[k-1]*(4k-2)//(k+1)。\"\"\"\n    cat = [1]\n    for k in range(1, limit + 1):\n        cat.append(cat[k - 1] * (4 * k - 2) // (k + 1))\n    return cat\n\n\ndef catalan_dp(n):\n    \"\"\"动态规划。返回 (ans, table)。\n\n    table[i][j] = 已经 push 了 i 个、已经 pop 了 j 个的方案数\n        table[0][0] = 1\n        table[i][j] = table[i-1][j]        （这一步 push 第 i 个数）\n                    + table[i][j-1]        （这一步 pop，要求栈非空：j <= i）\n    答案 table[n][n]。\n    \"\"\"\n    table = [[0] * (n + 1) for _ in range(n + 1)]\n    table[0][0] = 1\n    for i in range(n + 1):\n        for j in range(n + 1):\n            if i == 0 and j == 0:\n                continue\n            v = 0\n            if i >= 1:\n                v += table[i - 1][j]               # push 第 i 个\n            if j >= 1 and j <= i:                  # pop：栈里必须有货\n                v += table[i][j - 1]\n            table[i][j] = v\n    return table[n][n], table\n\n\ndef catalan_comb(n):\n    \"\"\"组合数公式：C(2n, n) / (n+1)。Python 整数是任意精度，直接阶乘相除。\"\"\"\n    return math.factorial(2 * n) // (math.factorial(n) * math.factorial(n + 1))\n\n\ndef enumerate_outputs(n):\n    \"\"\"暴力：枚举所有合法 push/pop 序列，收集真正得到的不同输出序列。\n\n    返回按字典序排好的列表。只在 n 较小时调用 —— 序列条数就是卡特兰数，\n    n=10 已经有 16796 条了。\n    \"\"\"\n    seen = []\n\n    def dfs(next_num, stack, out):\n        if len(out) == n:                       # 全部出栈 = 得到一个完整序列\n            seen.append(tuple(out))\n            return\n        if next_num <= n:                       # 选择 push\n            stack.append(next_num)\n            dfs(next_num + 1, stack, out)\n            stack.pop()\n        if stack:                               # 选择 pop（栈非空才行）\n            v = stack.pop()\n            out.append(v)\n            dfs(next_num, stack, out)\n            out.pop()\n            stack.append(v)\n\n    dfs(1, [], [])\n    return seen\n\n\n# ---------------------------------------------------------------- 展示部分\n\ndef show_dp_table(table, n):\n    \"\"\"打印 DP 表：行 = 已 push 的个数 i，列 = 已 pop 的个数 j。\"\"\"\n    w = max(5, len(str(table[n][n])) + 2)\n    print(\"    \" + \"\".rjust(5) + \"\".join((\"j=\" + str(j)).rjust(w)\n                                        for j in range(n + 1)))\n    for i in range(n + 1):\n        cells = []\n        for j in range(n + 1):\n            if j > i:\n                cells.append(\"--\".rjust(w))     # 不可能状态：pop 比 push 还多\n            else:\n                cells.append(str(table[i][j]).rjust(w))\n        print(\"    \" + (\"i=\" + str(i)).rjust(5) + \"\".join(cells))\n\n\ndef show_sequences(seqs, n):\n    \"\"\"把枚举出的输出序列一条条列出来（只在数量少的时候调用）。\"\"\"\n    for s in seqs:\n        print(\"      \" + \" \".join(str(x) for x in s))\n\n\n# ---------------------------------------------------------------- 输入输出\n\ndef make_reader():\n    \"\"\"每次吐一个空白分隔的 token，取完返回 None。统一 readline()，三环境通用。\"\"\"\n    buf = []\n\n    def nxt():\n        while not buf:\n            line = sys.stdin.readline()\n            if not line:                  # EOF / Ctrl+Z\n                return None\n            # 反序入栈，pop() 才是 O(1)（写 pop(0) 会退化成 O(n^2)）\n            buf.extend(reversed(line.split()))\n        return buf.pop()\n\n    return nxt\n\n\ndef is_uint(s):\n    \"\"\"s 是否为纯十进制数字串（允许前导零，拒绝空串 / 正负号 / 小数点）。\"\"\"\n    if not s:\n        return False\n    for ch in s:\n        if ch < \"0\" or ch > \"9\":\n            return False\n    return True\n\n\ndef main():\n    nxt = make_reader()\n    cat = catalan_recur(MAXN)             # 递推表一次算好，供 [3] 使用\n\n    case = 0\n    answers = []\n\n    while True:\n        tok = nxt()\n        if tok is None:                   # 读到 EOF：正常结束\n            break\n        if not is_uint(tok):\n            print(\"[!] n must be a decimal integer, got \" + repr(tok[:32]),\n                  file=sys.stderr)\n            return\n        if len(tok) > 9:\n            # 必须先拦长度再 int()：Python 3.11+ 对超过 4300 位的数字串转 int\n            # 会直接抛 ValueError（traceback），而不是 [!] 报错。\n            print(\"[!] n is far out of range [1, \" + str(MAXN) + \"]: a \"\n                  + str(len(tok)) + \"-digit number\", file=sys.stderr)\n            return\n        n = int(tok)\n        if n < 1 or n > MAXN:\n            print(\"[!] n out of range [1, \" + str(MAXN) + \"]: \" + str(n),\n                  file=sys.stderr)\n            return\n\n        case += 1\n        print(\"\")\n        print(\"=\" * 62)\n        print(\"Case \" + str(case) + \"    n = \" + str(n))\n        print(\"=\" * 62)\n\n        # ---- [1] 暴力枚举 ----\n        print(\"\")\n        print(\"[1] 暴力枚举：把所有合法的 push/pop 序列走一遍，收集不同的输出序列\")\n        brute = None\n        if n <= BRUTE_LIMIT:\n            # DFS 是\"先尽量 push\"，产出的顺序本身是逆字典序（3 2 1 在前），\n            # 这里排一下再打印，标题写\"字典序\"才名副其实。\n            seqs = sorted(enumerate_outputs(n))\n            brute = len(seqs)\n            print(\"    共 \" + str(len(seqs)) + \" 种\")\n            if n <= LIST_LIMIT:\n                print(\"    全部列出来（字典序）：\")\n                show_sequences(seqs, n)\n            else:\n                print(\"    （n > \" + str(LIST_LIMIT) + \"，序列太多，这里只报数量）\")\n        else:\n            print(\"    （n > \" + str(BRUTE_LIMIT) + \"，枚举太慢，跳过；\"\n                  \"看下面三套公式的结果）\")\n\n        # ---- [2] 动态规划 ----\n        print(\"\")\n        print(\"[2] 动态规划  table[i][j] = 已 push i 个、已 pop j 个 的方案数\")\n        print(\"    转移：table[i][j] = table[i-1][j] (push) + table[i][j-1] (pop，需 j<=i)\")\n        dp_ans, table = catalan_dp(n)\n        if n <= TABLE_LIMIT:\n            show_dp_table(table, n)\n        else:\n            print(\"    （n > \" + str(TABLE_LIMIT) + \"，表太大不打印）\")\n        print(\"    答案 table[\" + str(n) + \"][\" + str(n) + \"] = \" + str(dp_ans))\n\n        # ---- [3] 卡特兰递推 ----\n        print(\"\")\n        print(\"[3] 卡特兰递推  Cat(k) = Cat(k-1) * (4k-2) // (k+1)\")\n        show_k = min(n, 12)\n        head = \" \".join(str(cat[k]) for k in range(show_k + 1))\n        if n <= show_k:\n            print(\"    Cat(0..\" + str(n) + \") = \" + head)\n        else:\n            print(\"    Cat(0..\" + str(show_k) + \") = \" + head\n                  + \"   (共 \" + str(n) + \" 步，中间省略)\")\n        recur_ans = cat[n]\n        print(\"    Cat(\" + str(n) + \") = \" + str(recur_ans))\n\n        # ---- [4] 组合数公式 ----\n        print(\"\")\n        print(\"[4] 组合数公式  Cat(n) = C(2n, n) / (n+1)\")\n        c2n = math.factorial(2 * n) // (math.factorial(n) * math.factorial(n))\n        comb_ans = catalan_comb(n)\n        print(\"    C(\" + str(2 * n) + \", \" + str(n) + \") = \" + str(c2n)\n              + \"，\" + str(c2n) + \" / (\" + str(n) + \"+1) = \" + str(comb_ans))\n\n        # ---- Sum check ----\n        print(\"\")\n        print(\"[5] Sum check 交叉验证\")\n        parts = []\n        if brute is not None:\n            parts.append(\"暴力 \" + str(brute))\n        parts.append(\"DP \" + str(dp_ans))\n        parts.append(\"递推 \" + str(recur_ans))\n        parts.append(\"组合 \" + str(comb_ans))\n        ok = (dp_ans == recur_ans == comb_ans) and (brute is None or brute == dp_ans)\n        print(\"    \" + \" == \".join(parts) + \"  ->  \" + (\"OK\" if ok else \"MISMATCH\"))\n        if not ok:\n            print(\"[!] Sum check FAILED for n = \" + str(n), file=sys.stderr)\n\n        print(\"\")\n        print(\"  >>> 答案: \" + str(recur_ans))\n\n        answers.append(recur_ans)\n        sys.stdout.flush()\n\n    # 末尾按 OJ 标准格式再打一遍，便于和 catalan.py 的输出逐字比对\n    if answers:\n        print(\"\")\n        print(\"=\" * 62)\n        print(\"OJ 标准格式输出（提交请用 catalan.py，本文件仅供本地学习）\")\n        print(\"=\" * 62)\n        for a in answers:\n            print(a)\n        sys.stdout.flush()\n\n\nif __name__ == \"__main__\":\n    main()\n"}, {"label": "C 实现", "file": "catalan.c", "lang": "c", "stripped": "#include <stdio.h>\n\n#define MAXN     18\n#define MAXLEN   64\n\nstatic long long cat[MAXN + 1];\n\nstatic char line[MAXLEN + 8];\nstatic char *cursor = NULL;\n\n\nstatic int read_line(void) {\n    int i = 0;\n\n    for (;;) {\n        int c = fgetc(stdin);\n\n        if (c == EOF) {\n            if (i == 0) {\n                return 0;\n            }\n            line[i] = '\\0';\n            return 1;\n        }\n        if (c == '\\n') {\n            line[i] = '\\0';\n            return 1;\n        }\n        if (c == '\\0') {\n            line[i] = '\\0';\n            return -2;\n        }\n        if (i >= (int)sizeof(line) - 1) {\n            line[i] = '\\0';\n            return -1;\n        }\n        line[i] = (char)c;\n        i++;\n    }\n}\n\n\nstatic int next_token(char *out, int cap) {\n    for (;;) {\n        if (cursor == NULL || *cursor == '\\0') {\n            int r = read_line();\n            if (r <= 0) {\n                return r;\n            }\n            cursor = line;\n        }\n        while (*cursor == ' ' || *cursor == '\\t' ||\n               *cursor == '\\r' || *cursor == '\\n') {\n            cursor++;\n        }\n        if (*cursor == '\\0') {\n            continue;\n        }\n\n        int n = 0;\n        while (*cursor != '\\0' && *cursor != ' ' && *cursor != '\\t' &&\n               *cursor != '\\r' && *cursor != '\\n') {\n            if (n >= cap - 1) {\n                return -3;\n            }\n            out[n++] = *cursor++;\n        }\n        out[n] = '\\0';\n        return 1;\n    }\n}\n\n\nstatic const char *why_neg(int st) {\n    if (st == -1) {\n        return \"line too long\";\n    }\n    if (st == -2) {\n        return \"line contains a NUL byte\";\n    }\n    return \"token too long\";\n}\n\n\nstatic int parse_ll(const char *s, long long *out) {\n    long long v = 0;\n    int len = 0;\n\n    if (*s == '\\0') {\n        return 0;\n    }\n    for (; *s; s++) {\n        if (*s < '0' || *s > '9') {\n            return 0;\n        }\n        len++;\n        if (len > 9) {\n            return 0;\n\n        }\n        v = v * 10 + (*s - '0');\n    }\n    *out = v;\n    return 1;\n}\n\nint main(void) {\n    char tok[MAXLEN];\n    int st;\n\n\n    cat[0] = 1;\n    for (int k = 1; k <= MAXN; k++) {\n        cat[k] = cat[k - 1] * (4LL * k - 2) / (k + 1);\n    }\n\n    for (;;) {\n        st = next_token(tok, MAXLEN);\n        if (st == 0) {\n            break;\n        }\n        if (st < 0) {\n            fprintf(stderr, \"[!] %s (max %d chars)\\n\", why_neg(st), MAXLEN - 1);\n            return 0;\n        }\n\n        long long n;\n        if (!parse_ll(tok, &n)) {\n            fprintf(stderr, \"[!] n must be a decimal integer, got \\\"%s\\\"\\n\", tok);\n            return 0;\n        }\n        if (n < 1 || n > MAXN) {\n            fprintf(stderr, \"[!] n out of range [1, %d]: %lld\\n\", MAXN, n);\n            return 0;\n        }\n\n\n        printf(\"%lld\\n\", cat[n]);\n        fflush(stdout);\n    }\n\n    return 0;\n}\n", "original": "/*\n * 车厢调度 —— 栈能得到多少种输出序列（卡特兰数）\n * ==============================================\n * 算法：整个过程 = n 次 push 与 n 次 pop 排成一列，唯一约束是任何时刻\n *       pop 的次数不能超过 push 的次数（栈空弹不出东西），合法序列数\n *       就是第 n 个卡特兰数：\n *\n *           Cat(0) = 1\n *           Cat(k) = Cat(k-1) * (4k - 2) / (k + 1)      -- 整数递推，数学上整除\n *\n *       n <= 18 时 Cat(18) = 477638700，32 位 int 其实也装得下；\n *       但本文件全程用 long long —— 换个题（比如改走组合数路线，\n *       中间量 C(36,18) = 9075135300 就已经溢出 int32 了）就不会栽跟头。\n *\n * Input:  若干行，每行一个整数 n (1 <= n <= 18)，**读到文件结束（EOF）**\n * Output: 对每个 n 输出一行答案（每组一行，**没有 Case i 前缀**）\n *\n * Compile: gcc -O2 -o catalan catalan.c\n * Run:     ./catalan < input.txt\n *   需要 C99 以上（循环内声明变量等）；gcc / clang 默认就是 gnu17。\n *\n * ⚠️⚠️ 本机没有任何 C 编译器（gcc / clang / tcc / cl / zig 全无），\n *      本文件**从未编译、从未运行验证过**。逻辑与 catalan.py 逐行对应，\n *      但请在使用前自行编译核对。\n */\n\n#include <stdio.h>\n\n#define MAXN     18            /* 题面 n <= 18 */\n#define MAXLEN   64            /* token 长度上限；题面 n 最多 2 位 */\n\nstatic long long cat[MAXN + 1];\n\nstatic char line[MAXLEN + 8];\nstatic char *cursor = NULL;     /* 本行读到的位置；NULL 表示还没读任何一行 */\n\n/*\n * 读入一行到 line（换行符丢弃，末尾补 '\\0'）。\n *   返回  1 = 成功\n *         0 = EOF（一个字符都没读到）\n *        -1 = 这一行太长，超出缓冲区\n *        -2 = 这一行里含 NUL 字节\n *\n * ★ 为什么不用 fgets：fgets(buf, n, fp) 读满 n-1 个字符就立刻返回，\n *   **且不会告诉你它截断了**；事后想补救也不行 —— 用 strlen 数长度会被\n *   输入里的 '\\0' 骗过，用 feof 判文件尾同样不成立（fgets 凑满字符数就返回，\n *   那一刻根本没探文件尾，EOF 标志还是 0）。索性用 fgetc 逐字符读，\n *   读了多少个字符由我们自己数（i），四种情况各走各的分支，没有猜测空间。\n */\nstatic int read_line(void) {\n    int i = 0;\n\n    for (;;) {\n        int c = fgetc(stdin);\n\n        if (c == EOF) {\n            if (i == 0) {\n                return 0;                      /* 一个字符都没读到 = 流已结束 */\n            }\n            line[i] = '\\0';\n            return 1;                          /* 文件最后一行没有换行符 */\n        }\n        if (c == '\\n') {\n            line[i] = '\\0';                    /* 换行符丢掉，不留给 token */\n            return 1;\n        }\n        if (c == '\\0') {\n            line[i] = '\\0';\n            return -2;                         /* 文本输入不该出现 NUL 字节 */\n        }\n        if (i >= (int)sizeof(line) - 1) {\n            line[i] = '\\0';\n            return -1;                         /* 缓冲区满了还有后续 => 行太长 */\n        }\n        line[i] = (char)c;\n        i++;\n    }\n}\n\n/*\n * 取一个空白分隔的 token 放进 out（容量 cap）。\n *   返回  1 = 成功\n *         0 = EOF\n *        -1 = 整行太长（read_line 判定）\n *        -2 = 整行含 NUL 字节（read_line 判定）\n *        -3 = token 本身太长\n */\nstatic int next_token(char *out, int cap) {\n    for (;;) {\n        if (cursor == NULL || *cursor == '\\0') {\n            int r = read_line();\n            if (r <= 0) {\n                return r;              /* 0 = EOF；负值 = 行太长/含 NUL */\n            }\n            cursor = line;\n        }\n        while (*cursor == ' ' || *cursor == '\\t' ||\n               *cursor == '\\r' || *cursor == '\\n') {\n            cursor++;\n        }\n        if (*cursor == '\\0') {\n            continue;                              /* 空行：接着读下一行 */\n        }\n\n        int n = 0;\n        while (*cursor != '\\0' && *cursor != ' ' && *cursor != '\\t' &&\n               *cursor != '\\r' && *cursor != '\\n') {\n            if (n >= cap - 1) {\n                return -3;                         /* token 超长 */\n            }\n            out[n++] = *cursor++;\n        }\n        out[n] = '\\0';\n        return 1;\n    }\n}\n\n/* 把 next_token 的负返回值翻译成给人看的短语，现场排障时能一眼看出是哪种超限 */\nstatic const char *why_neg(int st) {\n    if (st == -1) {\n        return \"line too long\";\n    }\n    if (st == -2) {\n        return \"line contains a NUL byte\";\n    }\n    return \"token too long\";\n}\n\n/*\n * 把纯数字 token 解析成 long long。\n *   成功返回 1 并写入 *out；含非数字字符 / 空串 / 过长 返回 0。\n *\n * 不用 strtoll —— 它太宽松：\"0x1A\" 会解成 0、\"12abc\" 会截断成 12，\n * 都是静默给出一个错值的经典坑（CLAUDE.md 陷阱 13）。\n */\nstatic int parse_ll(const char *s, long long *out) {\n    long long v = 0;\n    int len = 0;\n\n    if (*s == '\\0') {\n        return 0;\n    }\n    for (; *s; s++) {\n        if (*s < '0' || *s > '9') {\n            return 0;                              /* 只认十进制数字 */\n        }\n        len++;\n        if (len > 9) {\n            return 0;      /* 题面 n <= 18（2 位）；9 位已是极宽松的上限，\n                              顺带保证下面的累加绝不会溢出 */\n        }\n        v = v * 10 + (*s - '0');\n    }\n    *out = v;\n    return 1;\n}\n\nint main(void) {\n    char tok[MAXLEN];\n    int st;\n\n    /* 预计算卡特兰数 Cat(0..MAXN)，多组输入直接查表 */\n    cat[0] = 1;\n    for (int k = 1; k <= MAXN; k++) {\n        cat[k] = cat[k - 1] * (4LL * k - 2) / (k + 1);\n    }\n\n    for (;;) {\n        st = next_token(tok, MAXLEN);\n        if (st == 0) {\n            break;                                 /* 读到 EOF：正常结束 */\n        }\n        if (st < 0) {\n            fprintf(stderr, \"[!] %s (max %d chars)\\n\", why_neg(st), MAXLEN - 1);\n            return 0;\n        }\n\n        long long n;\n        if (!parse_ll(tok, &n)) {\n            fprintf(stderr, \"[!] n must be a decimal integer, got \\\"%s\\\"\\n\", tok);\n            return 0;\n        }\n        if (n < 1 || n > MAXN) {\n            fprintf(stderr, \"[!] n out of range [1, %d]: %lld\\n\", MAXN, n);\n            return 0;\n        }\n\n        /* 逐组输出（与 catalan.py 保持一致）：本题是读到 EOF 才结束的格式，\n           若攒到读完再打，终端里不按 Ctrl+Z 就一个答案都看不到。 */\n        printf(\"%lld\\n\", cat[n]);\n        fflush(stdout);\n    }\n\n    return 0;\n}\n"}, {"label": "验证脚本 verify_catalan.py", "file": "verify_catalan.py", "lang": "py", "stripped": "import ast\nimport importlib.util\nimport math\nimport os\nimport subprocess\nimport sys\nimport threading\nimport time\n\nHERE = os.path.dirname(os.path.abspath(__file__))\nMINI = os.path.join(HERE, \"catalan.py\")\nDETAILED = os.path.join(HERE, \"catalan_detailed.py\")\n\ndef _load(path, modname):\n    spec = importlib.util.spec_from_file_location(modname, path)\n    mod = importlib.util.module_from_spec(spec)\n    spec.loader.exec_module(mod)\n    return mod\n\nmini = _load(MINI, \"catalan_under_test\")\ndetailed = _load(DETAILED, \"catalan_detailed_under_test\")\n\ncatalan_table = mini.catalan_table\nis_uint = mini.is_uint\nrecur = detailed.catalan_recur\ndp = detailed.catalan_dp\ncomb = detailed.catalan_comb\nenumerate_outputs = detailed.enumerate_outputs\n\nANCHORS = [\n\n    (1, 1, \"-\"),\n    (2, 2, \"题面样例：2 -> 2\"),\n    (3, 5, \"题面样例：3 -> 5\"),\n    (4, 14, \"-\"),\n    (5, 42, \"-\"),\n    (6, 132, \"-\"),\n    (7, 429, \"-\"),\n    (8, 1430, \"-\"),\n    (9, 4862, \"-\"),\n    (10, 16796, \"-\"),\n    (11, 58786, \"-\"),\n    (12, 208012, \"-\"),\n    (13, 742900, \"-\"),\n    (14, 2674440, \"-\"),\n    (15, 9694845, \"-\"),\n    (16, 35357670, \"-\"),\n    (17, 129644790, \"-\"),\n    (18, 477638700, \"题面最大 n=18；仍未超出 32 位 int\"),\n]\n\ndef expected_by_comb(n):\n    return math.factorial(2 * n) // (math.factorial(n) * math.factorial(n + 1))\n\ndef check_anchors():\n    fails = []\n    cat = catalan_table(18)\n    for n, want, why in ANCHORS:\n        got = cat[n]\n        if got != want:\n            fails.append(\"锚定【%s】Cat(%d) = %d，期望 %d\" % (why, n, got, want))\n        exp = expected_by_comb(n)\n        if got != exp:\n            fails.append(\"Cat(%d) = %d，组合数公式独立算出 %d\" % (n, got, exp))\n    return fails\n\ndef brute_by_operations(n):\n    seen = set()\n\n    def dfs(next_num, stack, out):\n        if len(out) == n:\n            seen.add(tuple(out))\n            return\n        if next_num <= n:\n            stack.append(next_num)\n            dfs(next_num + 1, stack, out)\n            stack.pop()\n        if stack:\n            v = stack.pop()\n            out.append(v)\n            dfs(next_num, stack, out)\n            out.pop()\n            stack.append(v)\n\n    dfs(1, [], [])\n    return len(seen)\n\ndef stack_generable(target, n):\n    stack = []\n    next_num = 1\n    for x in target:\n        while next_num <= n and (not stack or stack[-1] != x):\n            stack.append(next_num)\n            next_num += 1\n        if stack and stack[-1] == x:\n            stack.pop()\n        else:\n            return False\n    return True\n\ndef brute_by_permutations(n):\n    if n > 8:\n        return None\n    perms = []\n\n    def rec(prefix, rest):\n        if not rest:\n            perms.append(tuple(prefix))\n            return\n        for i in range(len(rest)):\n            rec(prefix + [rest[i]], rest[:i] + rest[i + 1:])\n\n    rec([], list(range(1, n + 1)))\n    return sum(1 for p in perms if stack_generable(p, n))\n\ndef check_brute():\n    fails = []\n    total = 0\n    for n in range(1, 10):\n        got_ops = brute_by_operations(n)\n        want = expected_by_comb(n)\n        total += 1\n        if got_ops != want:\n            fails.append(\"暴力一 n=%d：枚举操作序列得 %d，期望 %d\" % (n, got_ops, want))\n\n        got_perms = brute_by_permutations(n)\n        if got_perms is not None:\n            total += 1\n            if got_perms != want:\n                fails.append(\"暴力二 n=%d：枚举排列得 %d，期望 %d\" % (n, got_perms, want))\n    return total, fails\n\ndef check_detailed():\n    fails = []\n    total = 0\n    cat = catalan_table(18)\n\n    for n in range(1, 19):\n        total += 1\n        dp_ans, _table = dp(n)\n        recur_ans = recur(18)[n]\n        comb_ans = comb(n)\n        want = expected_by_comb(n)\n        for label, got in ((\"DP\", dp_ans), (\"递推\", recur_ans), (\"组合\", comb_ans)):\n            if got != want:\n                fails.append(\"详细版 %s Cat(%d) = %d，期望 %d\" % (label, n, got, want))\n        if cat[n] != want:\n            fails.append(\"提交版 Cat(%d) = %d，期望 %d\" % (n, cat[n], want))\n\n    for n in range(1, 10):\n        _ans, table = dp(n)\n        for i in range(n + 1):\n            for j in range(n + 1):\n                if i == 0 and j == 0:\n                    want = 1\n                else:\n                    want = 0\n                    if i >= 1:\n                        want += table[i - 1][j]\n                    if j >= 1 and j <= i:\n                        want += table[i][j - 1]\n                if table[i][j] != want:\n                    fails.append(\"DP 表 table[%d][%d] = %d，递推式要求 %d\"\n                                 % (i, j, table[i][j], want))\n\n    for n in range(1, 7):\n        seqs = enumerate_outputs(n)\n        total += 1\n        if len(seqs) != expected_by_comb(n):\n            fails.append(\"enumerate_outputs(%d) 得到 %d 条，期望 %d\"\n                         % (n, len(seqs), expected_by_comb(n)))\n        if len(set(seqs)) != len(seqs):\n            fails.append(\"enumerate_outputs(%d) 出现重复序列\" % n)\n        for s in seqs:\n            if sorted(s) != list(range(1, n + 1)):\n                fails.append(\"enumerate_outputs(%d) 产出非法序列 %r\" % (n, s))\n            elif not stack_generable(s, n):\n                fails.append(\"enumerate_outputs(%d) 产出的 %r 其实不能由栈生成\" % (n, s))\n\n    return total, fails\n\ndef run_mini(text):\n    p = subprocess.run([sys.executable, MINI], input=text,\n                       stdout=subprocess.PIPE, stderr=subprocess.PIPE,\n                       encoding=\"utf-8\", errors=\"replace\")\n    out = (p.stdout or \"\").replace(\"\\r\\n\", \"\\n\")\n    return out, p.stderr or \"\", p.returncode\n\ndef check_e2e():\n    fails = []\n    total = 0\n\n    clean_cases = [\n        (\"题面样例\", \"2\\n3\\n\", \"2\\n5\\n\"),\n        (\"单组\", \"3\\n\", \"5\\n\"),\n        (\"最大 n\", \"18\\n\", \"477638700\\n\"),\n        (\"空输入（什么都没有）\", \"\", \"\"),\n        (\"只有空行\", \"\\n\\n\\n\", \"\"),\n        (\"全部 n=1..18\", \"\".join(\"%d\\n\" % k for k in range(1, 19)),\n         \"\".join(\"%d\\n\" % ANCHORS[k - 1][1] for k in range(1, 19))),\n        (\"一行里塞多个 n（宽容解析）\", \"1 2 3\\n\", \"1\\n2\\n5\\n\"),\n        (\"数字跨行 / 多余空行\", \"\\n\\n2\\n\\n\\n3\\n\\n\", \"2\\n5\\n\"),\n        (\"CRLF 行尾\", \"2\\r\\n3\\r\\n\", \"2\\n5\\n\"),\n        (\"同组重复 n\", \"3\\n3\\n3\\n\", \"5\\n5\\n5\\n\"),\n        (\"没有末尾换行\", \"2\\n3\", \"2\\n5\\n\"),\n    ]\n    for why, text, want in clean_cases:\n        total += 1\n        out, err, _rc = run_mini(text)\n        if out != want:\n            fails.append(\"e2e【%s】stdout=%r，期望 %r\" % (why, out, want))\n        if err != \"\":\n            fails.append(\"e2e【%s】stderr 应为空，实为 %r\" % (why, err))\n\n    bad_cases = [\n        (\"非数字\", \"abc\\n\", \"\"),\n        (\"数字混字母（第 2 组才出错，第 1 组已输出）\", \"2\\n3a\\n\", \"2\\n\"),\n        (\"带负号\", \"-1\\n\", \"\"),\n        (\"小数点\", \"1.5\\n\", \"\"),\n        (\"越界 n=0\", \"0\\n\", \"\"),\n        (\"越界 n=19\", \"19\\n\", \"\"),\n        (\"越界 n=999\", \"999\\n\", \"\"),\n\n        (\"前面合法、后面越界\", \"2\\n3\\n100\\n\", \"2\\n5\\n\"),\n        (\"全角数字\", \"２\\n\", \"\"),\n        (\"10 位数字（超过长度闸门）\", \"1234567890\\n\", \"\"),\n\n        (\"5000 位数字（防 int() 抛 ValueError）\", \"9\" * 5000 + \"\\n\", \"\"),\n    ]\n    for why, text, want in bad_cases:\n        total += 1\n        out, err, _rc = run_mini(text)\n        if out != want:\n            fails.append(\"e2e【%s】stdout=%r，期望 %r\" % (why, out, want))\n        if not err.startswith(\"[!]\"):\n            fails.append(\"e2e【%s】stderr 应以 [!] 开头，实为 %r\" % (why, err))\n\n    return total, fails\n\ndef check_streaming_output(timeout=8.0):\n    p = subprocess.Popen([sys.executable, MINI], stdin=subprocess.PIPE,\n                         stdout=subprocess.PIPE, stderr=subprocess.PIPE,\n                         encoding=\"utf-8\", errors=\"replace\")\n    got = []\n\n    def rd():\n        for line in p.stdout:\n            got.append(line)\n\n    th = threading.Thread(target=rd)\n    th.daemon = True\n    th.start()\n\n    def feed(s, expect):\n        p.stdin.write(s)\n        p.stdin.flush()\n        time.sleep(0.6)\n        now = [x.strip() for x in got]\n        if now != expect:\n            return \"喂入 %r 后 stdout = %r，期望 %r\" % (s.strip(), now, expect)\n        return None\n\n    try:\n        err = feed(\"3\\n\", [\"5\"])\n        if err:\n            return \"(a) 逐组输出失效 —— \" + err\n        err = feed(\"4\\n\", [\"5\", \"14\"])\n        if err:\n            return \"(b) \" + err\n        if p.poll() is not None:\n            return \"(c) stdin 还没关，进程就已经退出了\"\n        p.stdin.close()\n    except Exception as e:\n        p.kill()\n        return \"写入 stdin 失败: %s\" % e\n\n    try:\n        p.wait(timeout=timeout)\n    except subprocess.TimeoutExpired:\n        p.kill()\n        return \"(c) 关闭 stdin（EOF）后 %.0f 秒仍未退出\" % timeout\n\n    th.join(2.0)\n    final = [x.strip() for x in got]\n    err_text = p.stderr.read() or \"\"\n    for h in (p.stdout, p.stderr):\n        try:\n            h.close()\n        except Exception:\n            pass\n    if final != [\"5\", \"14\"]:\n        return \"(c) 最终输出 = %r，期望 ['5', '14']\" % final\n    if err_text != \"\":\n        return \"(c) stderr 应为空，实为 %r\" % err_text\n    return None\n\ndef check_many_cases(n_cases=4000):\n    lines = []\n    want = []\n    for i in range(n_cases):\n        n = 1 + (i % 18)\n        lines.append(\"%d\" % n)\n        want.append(\"%d\" % expected_by_comb(n))\n    out, err, _rc = run_mini(\"\\n\".join(lines) + \"\\n\")\n    if err != \"\":\n        return 2, \"stderr 应为空，实为 %r\" % err[:120]\n    got = out.split(\"\\n\")\n    if got and got[-1] == \"\":\n        got.pop()\n    if len(got) != n_cases:\n        return 2, \"喂 %d 组，得到 %d 行\" % (n_cases, len(got))\n    for i in range(n_cases):\n        if got[i] != want[i]:\n            return 2, \"第 %d 行 = %r，期望 %r\" % (i + 1, got[i], want[i])\n    return n_cases, None\n\ndef ast_scan(path):\n    with open(path, \"r\", encoding=\"utf-8\") as f:\n        src = f.read()\n    tree = ast.parse(src, path)\n\n    bad = []\n    for node in ast.walk(tree):\n        if isinstance(node, ast.JoinedStr):\n            bad.append((\"f-string\", node.lineno))\n        elif isinstance(node, ast.NamedExpr):\n            bad.append((\"海象运算符 :=\", node.lineno))\n        elif isinstance(node, ast.Nonlocal):\n            bad.append((\"nonlocal\", node.lineno))\n        elif isinstance(node, ast.AnnAssign):\n            bad.append((\"变量类型注解\", node.lineno))\n        elif isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):\n            for a in list(node.args.args) + list(node.args.kwonlyargs):\n                if getattr(a, \"annotation\", None) is not None:\n                    bad.append((\"参数类型注解\", node.lineno))\n            if node.returns is not None:\n                bad.append((\"返回类型注解\", node.lineno))\n        elif isinstance(node, ast.Call):\n            f = node.func\n            if isinstance(f, ast.Name) and f.id == \"input\":\n                bad.append((\"input()\", node.lineno))\n            if isinstance(f, ast.Attribute) and f.attr == \"buffer\":\n                bad.append((\"sys.stdin.buffer\", node.lineno))\n    return bad\n\ndef main():\n    failures = []\n\n    failures += check_anchors()\n\n    brute_total, f = check_brute()\n    failures += f\n\n    det_total, f = check_detailed()\n    failures += f\n\n    e2e_total, f = check_e2e()\n    failures += f\n\n    err = check_streaming_output()\n    if err:\n        failures.append(\"逐组输出: \" + err)\n\n    many_total, err = check_many_cases()\n    if err:\n        failures.append(\"大批量: \" + err)\n\n    for path in (MINI, DETAILED):\n        for what, lineno in ast_scan(path):\n            failures.append(\"AST %s:%d 含禁用语法 %s\"\n                            % (os.path.basename(path), lineno, what))\n\n    if failures:\n        print(\"FAIL: %d 处\" % len(failures))\n        for x in failures[:5]:\n            print(\"  - \" + x)\n        return 1\n\n    print(\"OK: anchors %d | brute(ops+perms) %d | detailed 4-way %d | \"\n          \"stdout clean %d | streaming output ok | many-cases %d | AST clean (2 files)\"\n          % (len(ANCHORS), brute_total, det_total, e2e_total, many_total))\n    return 0\n\nif __name__ == \"__main__\":\n    raise SystemExit(main())\n", "original": "#!/usr/bin/env python3\n\"\"\"\n车厢调度 —— 自动对拍 / 自查脚本\n================================\n\n全部检查通过才打印 OK，任一失败打印前 5 条并 exit 1。\n\n检查项：\n\n  0. 锚定用例          题面样例 + n=1..18 的卡特兰数全表（写死）\n  1. 暴力一：枚举操作序列   n<=9，把所有合法 push/pop 序列走一遍，\n                            收集真正得到的不同输出序列，去重计数\n  2. 暴力二：枚举输出排列   n<=8，枚举 n! 个排列，逐个用模拟栈检验\n                            能不能由 1..n 生成 —— 与暴力一**完全独立**\n  3. 详细版四法一致         暴力 / DP / 递推 / 组合数与提交版逐例相同\n  4. 端到端 stdout          真起子进程跑 catalan.py：题面样例、单组、空输入、\n                            跨行、CRLF、同行多 token、非法输入、越界 n；\n                            正常情形断言 **stderr 为空**\n  5. EOF 语义              本题\"读到 EOF 结束\"，所以要分清两件事：\n                            (a) 数据给完但**没关 stdin** -> 程序应安静等待（没输出、没退出）\n                            (b) 关掉 stdin（EOF）-> 必须**立刻**输出全部答案并退出\n  6. 大批量                 4000 组一次喂进去，行数与内容都要对\n  7. AST 语法检查           提交版 / 详细版不得含 OJ 老 Python 不认的语法\n                            （f-string / buffer / nonlocal / 类型注解 / 海象 / input）\n                            注意：**不能用 grep** —— readline 含 read 子串会误报\n\n被测对象是**真正提交的文件** catalan.py 与 catalan_detailed.py，不是内部副本 ——\n避免\"验证脚本和实际代码各改各的\"这类漂移（CLAUDE.md 陷阱 10）。\n\"\"\"\n\nimport ast\nimport importlib.util\nimport math\nimport os\nimport subprocess\nimport sys\nimport threading\nimport time\n\nHERE = os.path.dirname(os.path.abspath(__file__))\nMINI = os.path.join(HERE, \"catalan.py\")\nDETAILED = os.path.join(HERE, \"catalan_detailed.py\")\n\n\ndef _load(path, modname):\n    \"\"\"载入待测文件本体（不是副本）。\"\"\"\n    spec = importlib.util.spec_from_file_location(modname, path)\n    mod = importlib.util.module_from_spec(spec)\n    spec.loader.exec_module(mod)\n    return mod\n\n\nmini = _load(MINI, \"catalan_under_test\")\ndetailed = _load(DETAILED, \"catalan_detailed_under_test\")\n\ncatalan_table = mini.catalan_table\nis_uint = mini.is_uint\nrecur = detailed.catalan_recur\ndp = detailed.catalan_dp\ncomb = detailed.catalan_comb\nenumerate_outputs = detailed.enumerate_outputs\n\n\n# ------------------------------------------------------------------ 锚定用例\n# n=1..18 的卡特兰数写死在这里。这些值不是手抄的 —— 它们与下面\n# `expected_by_comb()`（C(2n,n)/(n+1)，Python 任意精度独立算）逐项核对过，\n# 并与两条暴力在各自范围内对拍过。\nANCHORS = [\n    # (n, 卡特兰数, 说明)\n    (1, 1, \"-\"),\n    (2, 2, \"题面样例：2 -> 2\"),\n    (3, 5, \"题面样例：3 -> 5\"),\n    (4, 14, \"-\"),\n    (5, 42, \"-\"),\n    (6, 132, \"-\"),\n    (7, 429, \"-\"),\n    (8, 1430, \"-\"),\n    (9, 4862, \"-\"),\n    (10, 16796, \"-\"),\n    (11, 58786, \"-\"),\n    (12, 208012, \"-\"),\n    (13, 742900, \"-\"),\n    (14, 2674440, \"-\"),\n    (15, 9694845, \"-\"),\n    (16, 35357670, \"-\"),\n    (17, 129644790, \"-\"),\n    (18, 477638700, \"题面最大 n=18；仍未超出 32 位 int\"),\n]\n\n\ndef expected_by_comb(n):\n    \"\"\"独立算期望值：C(2n, n) / (n+1)。用阶乘（任意精度），不依赖 math.comb。\"\"\"\n    return math.factorial(2 * n) // (math.factorial(n) * math.factorial(n + 1))\n\n\ndef check_anchors():\n    fails = []\n    cat = catalan_table(18)\n    for n, want, why in ANCHORS:\n        got = cat[n]\n        if got != want:\n            fails.append(\"锚定【%s】Cat(%d) = %d，期望 %d\" % (why, n, got, want))\n        exp = expected_by_comb(n)\n        if got != exp:\n            fails.append(\"Cat(%d) = %d，组合数公式独立算出 %d\" % (n, got, exp))\n    return fails\n\n\n# ------------------------------------------------------------------ 暴力一：枚举操作序列\n\ndef brute_by_operations(n):\n    \"\"\"把所有合法的 push/pop 序列走一遍，收集真正得到的不同输出序列。\n\n    这是\"从操作出发\"的暴力：每条合法操作序列产生一个输出序列。\n    \"\"\"\n    seen = set()\n\n    def dfs(next_num, stack, out):\n        if len(out) == n:\n            seen.add(tuple(out))\n            return\n        if next_num <= n:\n            stack.append(next_num)\n            dfs(next_num + 1, stack, out)\n            stack.pop()\n        if stack:\n            v = stack.pop()\n            out.append(v)\n            dfs(next_num, stack, out)\n            out.pop()\n            stack.append(v)\n\n    dfs(1, [], [])\n    return len(seen)\n\n\n# ------------------------------------------------------------------ 暴力二：枚举输出排列\n\ndef stack_generable(target, n):\n    \"\"\"检验排列 target 能否由栈把 1..n 依次 push 得到（贪心模拟）。\"\"\"\n    stack = []\n    next_num = 1\n    for x in target:\n        while next_num <= n and (not stack or stack[-1] != x):\n            stack.append(next_num)\n            next_num += 1\n        if stack and stack[-1] == x:\n            stack.pop()\n        else:\n            return False\n    return True\n\n\ndef brute_by_permutations(n):\n    \"\"\"枚举 n! 个排列，逐个用模拟栈检验 —— 与暴力一完全独立的另一条路。\"\"\"\n    if n > 8:\n        return None                      # 9! = 362880，太重；n<=8 足够\n    perms = []\n\n    def rec(prefix, rest):\n        if not rest:\n            perms.append(tuple(prefix))\n            return\n        for i in range(len(rest)):\n            rec(prefix + [rest[i]], rest[:i] + rest[i + 1:])\n\n    rec([], list(range(1, n + 1)))\n    return sum(1 for p in perms if stack_generable(p, n))\n\n\ndef check_brute():\n    fails = []\n    total = 0\n    for n in range(1, 10):\n        got_ops = brute_by_operations(n)\n        want = expected_by_comb(n)\n        total += 1\n        if got_ops != want:\n            fails.append(\"暴力一 n=%d：枚举操作序列得 %d，期望 %d\" % (n, got_ops, want))\n\n        got_perms = brute_by_permutations(n)\n        if got_perms is not None:\n            total += 1\n            if got_perms != want:\n                fails.append(\"暴力二 n=%d：枚举排列得 %d，期望 %d\" % (n, got_perms, want))\n    return total, fails\n\n\n# ------------------------------------------------------------------ 详细版四法\n\ndef check_detailed():\n    fails = []\n    total = 0\n    cat = catalan_table(18)\n\n    for n in range(1, 19):\n        total += 1\n        dp_ans, _table = dp(n)\n        recur_ans = recur(18)[n]\n        comb_ans = comb(n)\n        want = expected_by_comb(n)\n        for label, got in ((\"DP\", dp_ans), (\"递推\", recur_ans), (\"组合\", comb_ans)):\n            if got != want:\n                fails.append(\"详细版 %s Cat(%d) = %d，期望 %d\" % (label, n, got, want))\n        if cat[n] != want:\n            fails.append(\"提交版 Cat(%d) = %d，期望 %d\" % (n, cat[n], want))\n\n    # DP 表的每一格都必须满足递推式。\n    # 说明：这是用**同一张表的其它格子**按同一条递推式重算，属自洽性检查；\n    # 真正拦住\"值算错\"的是上面那几行与 expected_by_comb() 的比对。\n    for n in range(1, 10):\n        _ans, table = dp(n)\n        for i in range(n + 1):\n            for j in range(n + 1):\n                if i == 0 and j == 0:\n                    want = 1\n                else:\n                    want = 0\n                    if i >= 1:\n                        want += table[i - 1][j]\n                    if j >= 1 and j <= i:\n                        want += table[i][j - 1]\n                if table[i][j] != want:\n                    fails.append(\"DP 表 table[%d][%d] = %d，递推式要求 %d\"\n                                 % (i, j, table[i][j], want))\n\n    # 暴力枚举出的输出序列：条数正确、每条都必须真能由栈生成、且不重复\n    for n in range(1, 7):\n        seqs = enumerate_outputs(n)\n        total += 1\n        if len(seqs) != expected_by_comb(n):\n            fails.append(\"enumerate_outputs(%d) 得到 %d 条，期望 %d\"\n                         % (n, len(seqs), expected_by_comb(n)))\n        if len(set(seqs)) != len(seqs):\n            fails.append(\"enumerate_outputs(%d) 出现重复序列\" % n)\n        for s in seqs:\n            if sorted(s) != list(range(1, n + 1)):\n                fails.append(\"enumerate_outputs(%d) 产出非法序列 %r\" % (n, s))\n            elif not stack_generable(s, n):\n                fails.append(\"enumerate_outputs(%d) 产出的 %r 其实不能由栈生成\" % (n, s))\n\n    return total, fails\n\n\n# ------------------------------------------------------------------ 端到端\n\ndef run_mini(text):\n    \"\"\"起子进程跑 catalan.py（管道 stdin，等价于 OJ 环境）。\n\n    显式用 utf-8 + errors=\"replace\" 解码：子进程写出的中文 stderr 可能按\n    本机 locale（Windows 下常为 GBK）编码，交给 subprocess 自动解码时会\n    变成 None，紧接着 str 操作就 AttributeError。\n    \"\"\"\n    p = subprocess.run([sys.executable, MINI], input=text,\n                       stdout=subprocess.PIPE, stderr=subprocess.PIPE,\n                       encoding=\"utf-8\", errors=\"replace\")\n    out = (p.stdout or \"\").replace(\"\\r\\n\", \"\\n\")     # Windows 文本模式归一化\n    return out, p.stderr or \"\", p.returncode\n\n\ndef check_e2e():\n    fails = []\n    total = 0\n\n    # (说明, stdin, 期望 stdout)  —— stderr 必须为空\n    clean_cases = [\n        (\"题面样例\", \"2\\n3\\n\", \"2\\n5\\n\"),\n        (\"单组\", \"3\\n\", \"5\\n\"),\n        (\"最大 n\", \"18\\n\", \"477638700\\n\"),\n        (\"空输入（什么都没有）\", \"\", \"\"),\n        (\"只有空行\", \"\\n\\n\\n\", \"\"),\n        (\"全部 n=1..18\", \"\".join(\"%d\\n\" % k for k in range(1, 19)),\n         \"\".join(\"%d\\n\" % ANCHORS[k - 1][1] for k in range(1, 19))),\n        (\"一行里塞多个 n（宽容解析）\", \"1 2 3\\n\", \"1\\n2\\n5\\n\"),\n        (\"数字跨行 / 多余空行\", \"\\n\\n2\\n\\n\\n3\\n\\n\", \"2\\n5\\n\"),\n        (\"CRLF 行尾\", \"2\\r\\n3\\r\\n\", \"2\\n5\\n\"),\n        (\"同组重复 n\", \"3\\n3\\n3\\n\", \"5\\n5\\n5\\n\"),\n        (\"没有末尾换行\", \"2\\n3\", \"2\\n5\\n\"),\n    ]\n    for why, text, want in clean_cases:\n        total += 1\n        out, err, _rc = run_mini(text)\n        if out != want:\n            fails.append(\"e2e【%s】stdout=%r，期望 %r\" % (why, out, want))\n        if err != \"\":\n            fails.append(\"e2e【%s】stderr 应为空，实为 %r\" % (why, err))\n\n    # 非法 / 越界：出错点**之前**已经逐组打出去的答案会留在 stdout ——\n    # 这是逐组输出的固有代价，所以期望值要按\"出错前已经算对了几组\"逐个写清楚，\n    # 不能一律写空串。出错点及之后的组一个字节都不写。stderr 要带 [!] 前缀。\n    bad_cases = [\n        (\"非数字\", \"abc\\n\", \"\"),\n        (\"数字混字母（第 2 组才出错，第 1 组已输出）\", \"2\\n3a\\n\", \"2\\n\"),\n        (\"带负号\", \"-1\\n\", \"\"),\n        (\"小数点\", \"1.5\\n\", \"\"),\n        (\"越界 n=0\", \"0\\n\", \"\"),\n        (\"越界 n=19\", \"19\\n\", \"\"),\n        (\"越界 n=999\", \"999\\n\", \"\"),\n        # 逐组输出后，出错之前那几组已经打出去了 —— 这是\"逐组\"的固有代价，\n        # 换来的是\"敲一组立刻看见一组\"（见 check_streaming_output）。\n        (\"前面合法、后面越界\", \"2\\n3\\n100\\n\", \"2\\n5\\n\"),\n        (\"全角数字\", \"２\\n\", \"\"),\n        (\"10 位数字（超过长度闸门）\", \"1234567890\\n\", \"\"),\n        # ★ 回归：5000 位数字若直接丢给 int()，Python 3.11+ 会抛\n        # ValueError（\"Exceeds the limit (4300 digits)\"）—— 那是 traceback，\n        # 不是我们要的 [!] 报错。必须在 int() 之前先拦长度。\n        (\"5000 位数字（防 int() 抛 ValueError）\", \"9\" * 5000 + \"\\n\", \"\"),\n    ]\n    for why, text, want in bad_cases:\n        total += 1\n        out, err, _rc = run_mini(text)\n        if out != want:\n            fails.append(\"e2e【%s】stdout=%r，期望 %r\" % (why, out, want))\n        if not err.startswith(\"[!]\"):\n            fails.append(\"e2e【%s】stderr 应以 [!] 开头，实为 %r\" % (why, err))\n\n    return total, fails\n\n\ndef check_streaming_output(timeout=8.0):\n    \"\"\"★ 本题最容易让人以为\"程序坏了\"的地方：它是「读到 EOF 结束」的格式。\n\n    如果把答案攒到读完再一起打，那么在终端 / PyCharm 里只要不按\n    Ctrl+Z（Windows）或 Ctrl+D（Linux）给出 EOF，就**一个答案都看不到** ——\n    这正是\"输入了却没有任何输出\"的来源（本脚本的作者就踩过这一下）。\n\n    所以逐组喂、逐组验：\n\n      (a) 喂完第 1 组（stdin 不关）就应当看到第 1 个答案；\n      (b) 再喂第 2 组，应当看到第 2 个答案；\n      (c) 关掉 stdin（EOF）后进程才退出，且答案一个不多一个不少。\n    \"\"\"\n    p = subprocess.Popen([sys.executable, MINI], stdin=subprocess.PIPE,\n                         stdout=subprocess.PIPE, stderr=subprocess.PIPE,\n                         encoding=\"utf-8\", errors=\"replace\")\n    got = []\n\n    def rd():\n        for line in p.stdout:\n            got.append(line)\n\n    th = threading.Thread(target=rd)\n    th.daemon = True\n    th.start()\n\n    def feed(s, expect):\n        \"\"\"喂一组，稍等片刻，看此刻 stdout 是不是正好等于 expect。\"\"\"\n        p.stdin.write(s)\n        p.stdin.flush()\n        time.sleep(0.6)\n        now = [x.strip() for x in got]\n        if now != expect:\n            return \"喂入 %r 后 stdout = %r，期望 %r\" % (s.strip(), now, expect)\n        return None\n\n    try:\n        err = feed(\"3\\n\", [\"5\"])\n        if err:\n            return \"(a) 逐组输出失效 —— \" + err\n        err = feed(\"4\\n\", [\"5\", \"14\"])\n        if err:\n            return \"(b) \" + err\n        if p.poll() is not None:\n            return \"(c) stdin 还没关，进程就已经退出了\"\n        p.stdin.close()                          # 触发 EOF\n    except Exception as e:                       # noqa: BLE001\n        p.kill()\n        return \"写入 stdin 失败: %s\" % e\n\n    try:\n        p.wait(timeout=timeout)\n    except subprocess.TimeoutExpired:\n        p.kill()\n        return \"(c) 关闭 stdin（EOF）后 %.0f 秒仍未退出\" % timeout\n\n    th.join(2.0)\n    final = [x.strip() for x in got]\n    err_text = p.stderr.read() or \"\"\n    for h in (p.stdout, p.stderr):\n        try:\n            h.close()\n        except Exception:                        # noqa: BLE001\n            pass\n    if final != [\"5\", \"14\"]:\n        return \"(c) 最终输出 = %r，期望 ['5', '14']\" % final\n    if err_text != \"\":\n        return \"(c) stderr 应为空，实为 %r\" % err_text\n    return None\n\n\ndef check_many_cases(n_cases=4000):\n    \"\"\"大批量：一次喂 4000 组，行数与每行内容都要对。\"\"\"\n    lines = []\n    want = []\n    for i in range(n_cases):\n        n = 1 + (i % 18)\n        lines.append(\"%d\" % n)\n        want.append(\"%d\" % expected_by_comb(n))\n    out, err, _rc = run_mini(\"\\n\".join(lines) + \"\\n\")\n    if err != \"\":\n        return 2, \"stderr 应为空，实为 %r\" % err[:120]\n    got = out.split(\"\\n\")\n    if got and got[-1] == \"\":\n        got.pop()\n    if len(got) != n_cases:\n        return 2, \"喂 %d 组，得到 %d 行\" % (n_cases, len(got))\n    for i in range(n_cases):\n        if got[i] != want[i]:\n            return 2, \"第 %d 行 = %r，期望 %r\" % (i + 1, got[i], want[i])\n    return n_cases, None\n\n\ndef ast_scan(path):\n    \"\"\"按铁律 5 扫老 OJ 不认的语法，返回 [(说明, 行号)]，空 = 通过。\"\"\"\n    with open(path, \"r\", encoding=\"utf-8\") as f:\n        src = f.read()\n    tree = ast.parse(src, path)\n\n    bad = []\n    for node in ast.walk(tree):\n        if isinstance(node, ast.JoinedStr):\n            bad.append((\"f-string\", node.lineno))\n        elif isinstance(node, ast.NamedExpr):\n            bad.append((\"海象运算符 :=\", node.lineno))\n        elif isinstance(node, ast.Nonlocal):\n            bad.append((\"nonlocal\", node.lineno))\n        elif isinstance(node, ast.AnnAssign):\n            bad.append((\"变量类型注解\", node.lineno))\n        elif isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):\n            for a in list(node.args.args) + list(node.args.kwonlyargs):\n                if getattr(a, \"annotation\", None) is not None:\n                    bad.append((\"参数类型注解\", node.lineno))\n            if node.returns is not None:\n                bad.append((\"返回类型注解\", node.lineno))\n        elif isinstance(node, ast.Call):\n            f = node.func\n            if isinstance(f, ast.Name) and f.id == \"input\":\n                bad.append((\"input()\", node.lineno))\n            if isinstance(f, ast.Attribute) and f.attr == \"buffer\":\n                bad.append((\"sys.stdin.buffer\", node.lineno))\n    return bad\n\n\ndef main():\n    failures = []\n\n    failures += check_anchors()\n\n    brute_total, f = check_brute()\n    failures += f\n\n    det_total, f = check_detailed()\n    failures += f\n\n    e2e_total, f = check_e2e()\n    failures += f\n\n    err = check_streaming_output()\n    if err:\n        failures.append(\"逐组输出: \" + err)\n\n    many_total, err = check_many_cases()\n    if err:\n        failures.append(\"大批量: \" + err)\n\n    for path in (MINI, DETAILED):\n        for what, lineno in ast_scan(path):\n            failures.append(\"AST %s:%d 含禁用语法 %s\"\n                            % (os.path.basename(path), lineno, what))\n\n    if failures:\n        print(\"FAIL: %d 处\" % len(failures))\n        for x in failures[:5]:\n            print(\"  - \" + x)\n        return 1\n\n    print(\"OK: anchors %d | brute(ops+perms) %d | detailed 4-way %d | \"\n          \"stdout clean %d | streaming output ok | many-cases %d | AST clean (2 files)\"\n          % (len(ANCHORS), brute_total, det_total, e2e_total, many_total))\n    return 0\n\n\nif __name__ == \"__main__\":\n    raise SystemExit(main())\n"}];
